"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["90985"],{50536(e){e.exports=JSON.parse('{"id":"FIN-1339","slug":"venture-capital-method","term":"Venture Capital Method","also_known_as":[],"difficulty":"Advanced","definition":"The venture capital method is a way of valuing early-stage companies by estimating their value at a future exit, then discounting it back to today using the high rate of return that venture investors require.","explanation":["Young start-ups often have little revenue and no profits, making traditional valuation methods hard to apply. The venture capital method works backwards from a hoped-for exit.","The investor estimates the company\'s value at exit, often by applying a multiple to projected revenue or earnings, then discounts it at a target rate of return that reflects the high risk of failure. This gives a post-money valuation today. The investor\'s ownership is their investment divided by this value.","For example, an investor expects a start-up could be worth 200,000,000 in five years and requires a 50% annual return. Discounting gives a post-money value of about 26,300,000 today. To invest 5,000,000, the investor would ask for about 19% of the company.","The method is simple and reflects how many venture investors think. But results are highly sensitive to the exit value, timing and target return, all of which are very uncertain. Future funding rounds will also dilute the investor, which should be accounted for."],"note":"","total":1500,"prev":{"slug":"venture-capital","term":"Venture Capital"},"next":{"slug":"vertical-analysis","term":"Vertical Analysis"}}')}}]);